import {cityScene} from "./city-scene.js";
import {t,lang,setLang,hasLang,EDITOR,policyName,eventName,eventSummary} from './i18n.js';
import {buy,priceLabel,initStore,isTestStore} from './store.js';
import {LEVELS,levelOf,collapsePopulation,limitTemp,offeredPolicies,score,OFFER_SIZE,policyCost,supply,canSupply,revive,TUNING,POLICIES,COLLAPSE,newGame,metrics,canEnact,advance,preview,baseline,comparison,outcome,restoreGame,dateLabel,round,shocks,effectiveLand,LAND_COST,SHOCKS} from './engine.js';
const $=s=>document.querySelector(s),icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`,signed=n=>(n>0?'+':'')+n;
const SAVE_KEY=id=>'tomorrow-city.pace.v8.'+id,LAST_KEY='tomorrow-city.level',PROGRESS_KEY='tomorrow-city.progress';
const readJSON=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}};
const writeJSON=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
let progress=readJSON(PROGRESS_KEY,{cleared:[],best:{}});
const UNLOCK_ALL=true; // testing build: every city is playable from the start
const unlocked=id=>{if(UNLOCK_ALL)return true;const i=LEVELS.findIndex(l=>l.id===id);return i<=0||progress.cleared.includes(LEVELS[i-1].id);};
let level='chicago';try{level=localStorage.getItem(LAST_KEY)||'newark';}catch{level='newark';}
if(!LEVELS.some(l=>l.id===level))level='newark';
let state=newGame(undefined,level),selected=null,chart='employment',toastTimer,wonShown=false;
try{const saved=localStorage.getItem(SAVE_KEY(level));if(saved)state=restoreGame(JSON.parse(saved));}catch{}
wonShown=state.won;
function save(){try{localStorage.setItem(SAVE_KEY(state.level),JSON.stringify({version:8,level:state.level,seed:state.seed,actions:state.actions}));}catch{$('#save-status').textContent='此浏览器无法保存；请保持页面打开';}}
function summary(){return {year:state.year,date:dateLabel((state.finished?Math.max(0,state.year-1):state.year)),budget:state.budget,metrics:state.last||metrics(state),cumulativeDeaths:state.cumulativeDeaths,cumulativeEmissions:state.cumulativeEmissions,comparison:comparison(state),pending:state.queue,finished:state.finished,availablePolicies:POLICIES.filter(p=>canEnact(state,p.id)).map(p=>p.id)};}
function drawChart(){
 const L=k=>t(k),fields={employment:[L('employment'),'%'],emissions:[L('emissions'),''],temperature:[L('temperature'),'°C'],population:[L('population'),L('people')],budget:[L('budget'),L('coin')],waterStock:['淡水储备','指数'],minerals:['矿产储备','指数'],airPollution:['空气污染','游戏指数'],waterPollution:['水污染','游戏指数'],populationHealth:['居民健康','游戏指数'],totalMortality:['总死亡率','人 / 10万人·年'],backgroundWarming:['全球背景升温（较开局）','°C'],mortality:[L('mortality'),L('per100k')],coldMortality:[L('coldMortality'),L('per100k')]},[name,unit]=fields[chart];
 const actual=state.history,reference=baseline(state.seed,state.year),all=[...actual,...reference].map(r=>r[chart]);
 if(!actual.length){$('#trend-chart').innerHTML=`<div class="chart-empty">${t('chartEmpty')}</div>`;return;}
 const lo=chart==='population'?Math.min(...all)*.98:chart==='employment'?Math.min(80,...all)-2:Math.max(0,Math.min(...all)-2),hi=Math.max(...all)+Math.max(2,Math.max(...all)*.1),range=hi-lo||1;
 const x=i=>48+i*500/Math.max(1,actual.length-1),y=v=>134-(v-lo)/range*102;
 const path=rows=>rows.map((r,i)=>`${i?'L':'M'} ${x(i).toFixed(1)} ${y(r[chart]).toFixed(1)}`).join(' ');
 const grid=[0,.5,1].map(t=>{const v=lo+t*range;return `<line x1="48" x2="558" y1="${y(v)}" y2="${y(v)}" stroke="#e7eadf"/><text x="39" y="${y(v)+4}" text-anchor="end">${round(v)}</text>`;}).join('');
 $('#trend-chart').innerHTML=`<div class="chart-unit">${name}${unit?' · '+unit:''}</div><svg class="trend-svg" viewBox="0 0 580 160" role="img" aria-label="${name}趋势：最近一年 ${actual.at(-1)[chart]}，对照 ${reference.at(-1)[chart]}">${grid}<path d="${path(reference)}" fill="none" stroke="#b5bba7" stroke-dasharray="5 5" stroke-width="2"/><path d="${path(actual)}" fill="none" stroke="#4f7a43" stroke-width="3"/>${actual.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r[chart])}" r="3" fill="#4f7a43"><title>${dateLabel(i)}：${r[chart]} ${unit}</title></circle>`).join('')}<text x="48" y="156">2026</text><text x="285" y="156">${2026+Math.floor((actual.length-1)/2)}</text><text x="558" y="156" text-anchor="end">${2026+actual.length-1}</text></svg>`;
}
const isPhone=()=>!EDITOR;
const cityName=id=>{const L=levelOf(id);return lang==='en'?L.english:L.name;};
const cityBlurb=id=>{const L=levelOf(id);return L.blurb[lang==='en'?1:0];};
function startLevel(id,seed){level=id;try{localStorage.setItem(LAST_KEY,id);}catch{}const saved=readJSON(SAVE_KEY(id),null);state=saved&&seed===undefined?(()=>{try{return restoreGame(saved);}catch{return newGame(undefined,id);}})():newGame(seed,id);wonShown=state.won;selected=null;save();render();}
function showLevels(){open(`${top('leaf')}<h2 id="dialog-title">${t('levelPick')}</h2><div class="levels">${LEVELS.map(L=>{const open_=unlocked(L.id),done=progress.cleared.includes(L.id),b=progress.best[L.id];return `<button class="level-card${open_?'':' locked'}${done?' done':''}" data-level="${L.id}" ${open_?'':'disabled'}><span class="level-top"><b>${cityName(L.id)}</b><span>${t('pop',{n:L.size.toLocaleString()})}</span></span><span class="level-blurb">${cityBlurb(L.id)}</span><span class="level-foot">${t('goalYears',{n:L.goal})} · ${t('limitLine',{n:L.limitTemp})}${done?' · '+t('cleared'):''}${b?' · '+t('best',{n:b}):''}${open_?'':' · '+t('locked')}</span></button>`;}).join('')}</div>`);}
function showWin(){wonShown=true;const i=LEVELS.findIndex(l=>l.id===state.level),next=LEVELS[i+1],sc=score(state).total;if(!progress.cleared.includes(state.level))progress.cleared.push(state.level);progress.best[state.level]=Math.max(progress.best[state.level]||0,sc);writeJSON(PROGRESS_KEY,progress);open(`${top('leaf')}<div class="result-kicker">${t('score')} ${sc.toLocaleString()}</div><h2 id="dialog-title">${t('wonTitle',{city:cityName(state.level)})}</h2><p class="dialog-copy">${t('wonCopy',{n:state.year})}</p>${next?`<button class="primary-button" data-next="${next.id}"><span>${t('nextCity',{city:cityName(next.id)})}</span>${icon('arrow')}</button>`:`<p class="dialog-copy">${t('allCleared')}</p>`}<button class="dialog-secondary" data-action="close">${t('keepGoing')}</button>`);}
function renderReport(){const m=state.last||metrics(state),sc=score(state);const tiles=[[t('population'),Math.round(state.population).toLocaleString(),t('people')],[t('budget'),Math.round(state.budget),t('coin')],[t('employment'),m.employment,'%'],[t('emissions'),m.emissions,''],[t('temperature'),m.temperature,'°C'],[t('mortality'),m.mortality,t('per100k')],[t('coldMortality'),m.coldMortality,t('per100k')]];$('#report-card').innerHTML=`<div class="score"><span>${t('score')}</span><strong>${sc.total.toLocaleString()}</strong><small>${t('survived',{n:state.year})}${state.revives?' · '+t('revived',{n:state.revives}):''}</small></div><div class="report-tiles">${tiles.map(([k,v,u])=>`<div><span>${k}</span><b>${v}<i>${u}</i></b></div>`).join('')}</div>`;}
function render(){document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('#lang-button').textContent=lang==='en'?'中文':'EN';renderNews();renderReport();{const n=state.finished?Math.max(0,state.year-1):state.year;$('#city-year').innerHTML=`<b>${2026+n}</b><span>${cityName(state.level)} · ${t('cityPop',{n:Math.round(state.population).toLocaleString()})} · ${t('goalYears',{n:state.goal})}</span>`;}
 const n=(state.finished?Math.max(0,state.year-1):state.year),m=state.last||metrics(state),c=comparison(state);
 $('#round-label').textContent=`第 ${n+1} 年`;$('#decision-round').textContent=String(n+1).padStart(2,'0');$('#year-label').textContent=`${2026+n}`;
 $('#year-progress').innerHTML=`<small>已经营 ${state.year} 年 · 无年限</small>`;$('#year-progress').setAttribute('aria-label',`已经营 ${state.year} 年，无固定终点`);
 $('#survival-risk').innerHTML=`<strong>城市存续风险</strong><p>气候失控：年均日最高温 ≥${limitTemp(state)}°C，连续 ${COLLAPSE.hotYears} 年。当前 ${state.hotStreak} / ${COLLAPSE.hotYears} 年。</p><p>人口崩塌：≤${collapsePopulation(state).toLocaleString()} 人。当前 ${Math.round(state.population).toLocaleString()} 人。</p><small>任一达到则结束；均为游戏终局阈值，不是现实气候临界点。赤字会削弱就业并加剧迁出。</small>`;
 const period=state.last?dateLabel(state.last.year)+' 已结算':'首年初始估计';
 const stats=[['smile','城市人口',Math.round(state.population).toLocaleString(),'人',state.last?`出生 ${state.last.births} · 净迁入 ${state.last.migration}`:'住房、就业与环境共同影响',false],['coin','财政余额',state.budget,'币',period,state.budget<40],['shop','就业率',m.employment,'%',period,m.employment<85],['cloud','碳排指数',m.emissions,'',`累计减排 ${c.emissionsReduction}%`,false],['sun','年均日最高温',m.temperature,'°C',period,m.temperature>=35],['shield','高温死亡率',m.mortality,'',`人 / 10万人·年 · ${state.last?'已结算':'初始估计'}`,m.mortality>5],['leaf','累计高温死亡',state.cumulativeDeaths,'人',`较对照${c.avoidedDeaths>=0?'减少':'增加'} ${Math.abs(c.avoidedDeaths)} 人`,c.avoidedDeaths<0]];
 $('#stats').innerHTML=stats.map(([i,label,value,unit,note,warn])=>`<div class="stat ${warn?'warn':''}"><div class="stat-label">${icon(i)}${label}</div><div class="stat-value"><strong>${value}</strong><span>${unit}</span></div><div class="stat-foot">${note}</div></div>`).join('');
 $('#city-weather').textContent=m.heatwave?'热浪年份 · 健康系统承压':m.temperature>=33?'高温季 · 留意户外劳动与用电':'常规年份 · 为高温季提前布局';
 $('#city-scene').classList.toggle('hot',m.temperature>=35);
 $('#city-badge').textContent=`医疗 ${round(state.health)} · 热防护 ${round(state.protection)}`;
 $('#journal-text').textContent=state.journal;renderCity();const briefing=metrics(state,(state.finished?Math.max(0,state.year-1):state.year));$('#shock-briefing').textContent=state.finished?'城市已崩塌':`先选政策 → 年内被动遭遇事件 → 年终结算。${(state.year+1)%3===0?'今年会触发小冲击；':''}${(state.year+1)%10===0?'今年会触发大冲击；':''}新事件不会提前公开。`+(briefing.events.length?'持续中的冲击：'+briefing.events.map(e=>e.name+'（剩余 '+e.remaining+' 年）').join('、'):'目前无持续冲击。');$('#journal-date').textContent=state.last?dateLabel(state.last.year):'城市经营开始';
 const offer=offeredPolicies(state);$('#projects').innerHTML=POLICIES.map(p=>{const offered=offer.includes(p.id),available=canEnact(state,p.id),status=state.counts[p.id]>=p.limit?t('limit'):state.budget<policyCost(state,p.id)?t('noMoney'):state.land.vacant<(LAND_COST[p.id]||0)?t('noLand'):p.id==='carbon'&&state.land.industry<2?t('noIndustry'):(EDITOR?p.tradeoff:'');return `<button class="project ${selected===p.id?'selected':''} ${offered?'offered':'not-offered'} ${available?'':'blocked'}" data-id="${p.id}" aria-pressed="${selected===p.id}" aria-label="${policyName(p)}, ${policyCost(state,p.id)} ${t('coin')}${status?', '+status:''}" ${available?'':'disabled'}><span class="project-top"><span class="project-icon">${icon(p.icon)}</span><span class="project-cost">${policyCost(state,p.id)} ${t('coin')}</span></span><span class="project-name">${policyName(p)}</span><span class="project-summary">${status}</span><span class="policy-timing">${p.delay?p.delay+' 年后生效':p.id==='hours'?'仅当年有效':'当年生效'}</span></button>`;}).join('');
 if(selected&&isPhone()&&!offer.includes(selected))selected=null;const p=POLICIES.find(p=>p.id===selected);
 if(p){const f=preview(state,p.id),d=f.relative;$('#selection-detail').innerHTML=`<span class="selection-eyebrow">${p.tag} · 已实施 ${state.counts[p.id]} / ${Number.isFinite(p.limit)?p.limit:'不限'}</span><p>${p.description}${LAND_COST[p.id]?` 建设占用 ${LAND_COST[p.id]} 格空地；竣工前地图标为施工。`:p.id==='carbon'?' 退役 2 格工业用地，释放为空地。':''}</p><div class="forecast-heading">已知环境下的政策估计 · 不预知新冲击</div><div class="impact-pills"><span>就业 ${signed(d.employment)} 个百分点</span><span>碳排 ${signed(d.emissions)}</span><span>死亡率 ${signed(d.mortality)}</span><span>财政 ${signed(d.budget)} 币</span></div><p class="forecast-note">${p.delay?'延迟收益尚未计入本年影响。':''}新冲击尚未揭晓，实际结果可能不同。死亡率单位：人 / 10万人·年。</p>`;}
 else $('#selection-detail').innerHTML='<span class="selection-eyebrow">先想一步，再走一年</span><p>本年少一些排放，可能意味着少一些岗位；今年投入医疗和绿化，可能数年后才见效。点选政策，查看代价与生效时间。</p>';
 $('#build-button').disabled=!state.finished&&!p;$('#build-button span').textContent=state.finished?t('viewReport'):p?t('enact'):t('pick');$('#rest-button').hidden=state.finished;$('#rest-button').innerHTML=`<span>${t('wait')}</span>${icon('arrow')}`;const sb=$('#supply-button');sb.hidden=state.finished;sb.disabled=!canSupply(state);sb.innerHTML=`<span>${canSupply(state)?`${t('supply')} · ${t('fund')} +${TUNING.supply.budget} ${t('water')} +${TUNING.supply.water} ${t('minerals')} +${TUNING.supply.minerals}`:t('supplied')}</span><b>${priceLabel('supply')==='测试'?t('test'):priceLabel('supply')}</b>`;
 $('#budget-badge').innerHTML=`<b>${Math.round(state.budget)}</b> ${t('coin')}`;$('#budget-badge').classList.toggle('low',state.budget<40);$('#decision-title').textContent=state.finished?t('collapsedTitle'):t('decide');
 $('#policy-queue').innerHTML=state.queue.length?state.queue.map(q=>`<div class="queue-item"><span>${q.name}</span><b>${dateLabel(q.at)}</b></div>`).join(''):'<p class="empty-queue">暂无待生效政策。清洁能源、培训、绿化与医疗投资都需要时间。</p>';
 $('#chart-tabs').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.chart===chart)));drawChart();
}
function close(){$('#game-dialog').close();}
function open(html){$('#dialog-content').innerHTML=html;if(!$('#game-dialog').open)$('#game-dialog').showModal();}
const top=i=>`<div class="dialog-top"><div class="dialog-icon">${icon(i)}</div><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div>`;
function enact(id){state=advance(state,id);selected=null;save();newsYear=state.last.year;render();clearTimeout(toastTimer);$('#scene-toast').textContent=state.finished?t('reportReady'):t('settled',{y:2025+state.year});$('#scene-toast').classList.add('show');toastTimer=setTimeout(()=>$('#scene-toast').classList.remove('show'),2000);if(state.finished)showResult();else if(state.won&&!wonShown)showWin();return summary();}
function showResult(){const reason={climate:t('endClimate'),population:t('endPopulation'),both:t('endBoth')};const sc=score(state);open(`${top('leaf')}<div class="result-kicker">${t('score')} ${sc.total.toLocaleString()} · ${t('survived',{n:state.year})}</div><h2 id="dialog-title">${t('heldTo',{y:2025+state.year})}</h2><p class="dialog-copy">${reason[state.endReason]}</p><div class="result-grid"><div class="result-stat"><strong>${Math.round(state.population).toLocaleString()}</strong><span>${t('remaining')}</span></div><div class="result-stat"><strong>${state.last.temperature}°C</strong><span>${t('temperature')}</span></div><div class="result-stat"><strong>${state.last.emissions}</strong><span>${t('emissions')}</span></div></div><button class="primary-button" data-action="revive"><span>${t('reviveBtn',{y:2026+state.year})}</span><b class="price-tag">${isTestStore()?t('test'):priceLabel('revive')}</b></button><p class="dialog-footnote">${t('reviveNote',{p:TUNING.revive.population.toLocaleString(),c:TUNING.revive.cooling})} ${isTestStore()?t('testNote'):''}</p><button class="dialog-secondary" data-action="new">${t('retry')}</button><button class="dialog-secondary" data-action="close">${t('history')}</button>`);}
async function purchase(key){const r=await buy(key);if(!r.ok){toast(r.error);return false;}state=key==='revive'?revive(state):supply(state);save();render();toast(key==='revive'?t('revivedToast'):t('suppliedToast')+(r.test?` (${t('test')})`:''));return true;}
function toast(text){clearTimeout(toastTimer);$('#scene-toast').textContent=text;$('#scene-toast').classList.add('show');toastTimer=setTimeout(()=>$('#scene-toast').classList.remove('show'),2200);}
function help(){if(!EDITOR)return open(`${top('help')}<h2 id="dialog-title">${t('helpTitle')}</h2><ol><li>${t('help1')}</li><li>${t('help2')}</li><li>${t('help3')}</li><li>${t('help4')}</li></ol><p class="dialog-footnote">${t('helpNote')}</p><button class="primary-button" data-action="close"><span>${t('start')}</span>${icon('arrow')}</button>`);open(`${top('help')}<h2 id="dialog-title">政策会产生连锁反应。</h2><ol><li>每年最多执行一项政策，或维持现状。每年结算税收、政策支出及持续运维费用；没有固定年限，可持续经营到城市崩塌。</li><li>每 3 年触发小冲击（持续 1 年），每 10 年触发大冲击（持续 3 年）；每逢第 30、60、90…年叠加。包含外需、援助、技术突破、衰退与热浪。先执行政策，再揭晓当年新冲击；持续中的冲击可见。预览不偷看未来，存档和对照不会重抽。</li><li>就业影响财政收入。工业招商增加岗位和排放；淘汰产能立即减排但冲击就业，先完成培训可减轻冲击。</li><li>气温随季节与热浪变化。高温降低户外劳动产出，也增加制冷用电与模拟高温死亡率。空调、医疗和限工降低健康损失，但各有代价。</li><li>绿化在生效后缓解本地热岛。这里不会把本地一年的减排，错误地换算成下年全球降温。</li><li>年均日最高温连续 3 年达到 35°C，或人口降至 2 万人及以下，游戏结束。这是游戏阈值，不是现实气候临界点。财政赤字与失业通过就业、迁移和人口继续影响城市，不会立即终止。</li></ol><p class="dialog-footnote">死亡率仅指模型中的高温相关死亡，不是全因死亡率。人口随出生、死亡和迁移变化；死亡人数按当年人口计算。为增强策略反馈，高温死亡放大4倍、污染死亡放大3倍，基础净迁移放大2倍。所有系数与政策效应均为虚构游戏规则，未用真实数据标定。高温健康风险的方向参考 <a href="https://www.who.int/news-room/fact-sheets/detail/climate-change-heat-and-health" target="_blank" rel="noopener noreferrer">WHO《Heat and health》</a>，该来源不支持本游戏的具体数值。</p><button class="primary-button" data-action="close"><span>开始制定政策</span>${icon('arrow')}</button>`);}
$('#projects').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(!b||b.disabled)return;selected=b.dataset.id;render();$(`[data-id="${selected}"]`).focus({preventScroll:true});});
$('#build-button').addEventListener('click',()=>state.finished?showResult():selected&&enact(selected));$('#rest-button').addEventListener('click',()=>enact(null));$('#supply-button').addEventListener('click',e=>{const b=e.currentTarget;b.disabled=true;purchase('supply').finally(()=>render());});$('#help-button').addEventListener('click',help);$('#levels-button').addEventListener('click',showLevels);
$('#restart-button').addEventListener('click',()=>open(`${top('refresh')}<h2 id="dialog-title">${t('restartTitle')}</h2><p class="dialog-copy">${t('restartCopy')}</p><button class="primary-button" data-action="new"><span>${t('restart')}</span>${icon('arrow')}</button><button class="dialog-secondary" data-action="close">${t('keep')}</button>`));
$('#dialog-content').addEventListener('click',e=>{const l=e.target.closest('[data-lang]');if(l){setLang(l.dataset.lang);close();render();pendingLevels=true;help();return;}const pick=e.target.closest('[data-level],[data-next]');if(pick){close();startLevel(pick.dataset.level||pick.dataset.next);return;}const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='close'){close();if(pendingLevels){pendingLevels=false;showLevels();}}if(b.dataset.action==='revive'){b.disabled=true;purchase('revive').then(ok=>{if(ok)close();else b.disabled=false;});}if(b.dataset.action==='new'){close();startLevel(state.level,state.seed);}});
$('#chart-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-chart]');if(!b)return;chart=b.dataset.chart;render();});

const landMeta={forest:['森林','tree'],farmland:['农田','leaf'],residential:['住宅','shop'],industry:['工业','shop'],energy:['能源','sun'],water:['水域','water'],vacant:['空地','help']};
function renderLand(){const L=levelOf(state.level),land=state.land,order=['forest','farmland','residential','industry','energy','water','vacant'];
 $('#land-strip').innerHTML=`<div class="land-bar">${order.map(k=>`<span class="seg ${k}" style="flex:${land[k]}" title="${landMeta[k][0]} ${land[k]}%"></span>`).join('')}</div><div class="land-keys">${order.filter(k=>land[k]).map(k=>`<span><i class="dot ${k}"></i>${t('land_'+k)} ${land[k]}%</span>`).join('')}</div><p class="land-scale">${t('landScale',{a:L.area,t:(L.area/100).toFixed(L.area<20?2:1)})}</p>`;}
function renderCity(){renderLand();
 const m=state.last||metrics(state),land=state.land,operational=effectiveLand(state,Math.max(0,state.year-1));
 $('#city-map').innerHTML=cityScene(state,operational);
 $('#land-legend').innerHTML=Object.entries(land).map(([k,v])=>`<button data-land="${k}" class="land-key ${k}">${landMeta[k][0]} ${v}%</button>`).join('');
 $('#land-detail').textContent=`工业 ${operational.industry} 格运营 / ${land.industry-operational.industry} 格施工；可建设空地 ${land.vacant} 格。点击地块查看用途。`;
 const ledger={industrial:'工厂生产',housing:'住宅运营',fossilPower:'化石发电',extraction:'燃料采集',cleanLifecycle:'清洁能源生命周期',construction:'建设施工',services:'交通与服务',forestSink:'森林碳汇',external:'事件与限工调整'};
 $('#carbon-ledger').innerHTML='<h3>碳排放从哪里来？</h3><div class=ledger-grid>'+Object.entries(m.carbonLedger).map(([k,v])=>`<div><span>${ledger[k]}</span><b>${signed(v)}</b></div>`).join('')+`</div><p class=model-note>净排放 ${m.emissions}，各项为游戏指数，四舍五入可能有差异。CO₂ 与空气污染分别计算；烟雾只示意污染。</p>`;
 $('#health-chain').innerHTML=`<h3>污染 → 暴露 → 健康 → 死亡</h3><div class=health-meters><label>空气污染 ${state.airPollution}/100<meter min=0 max=100 value=${state.airPollution}></meter></label><label>水污染 ${state.waterPollution}/100<meter min=0 max=100 value=${state.waterPollution}></meter></label><label>居民健康 ${state.populationHealth}/100<meter min=0 max=100 value=${state.populationHealth}></meter></label></div><p>医疗能力 ${state.health} · 污染水暴露 ${m.waterExposure} · 本年污染额外死亡 ${state.last?m.pollutionDeaths:'待结算'} 人。</p><small>污染水体和缺水放大暴露，净水设施降低暴露；健康下降会增加污染死亡及高温脆弱性。高温死亡 ×4、污染死亡 ×3、基础迁移 ×2，强化策略反馈；均为虚构游戏参数。</small>`;
 $('#resource-summary').innerHTML=`<div><b>淡水 ${state.waterStock} / 100</b><meter min="0" max="100" value="${state.waterStock}"></meter><small>补给 − 居民与工业用水</small></div><div><b>矿产 ${state.minerals} / 100</b><meter min="0" max="100" value="${state.minerals}"></meter><small>开采消耗；循环利用缓解</small></div><div><b>住房容量 ${Math.round(operational.residential*7000).toLocaleString()}</b><small>人口超过容量会增加迁出</small></div>`;
 $('#climate-breakdown').innerHTML=`<strong>温度为什么变化？</strong><p>全球背景较开局 +${m.backgroundWarming.toFixed(2)}°C · 本地净热岛 ${m.heatIsland}°C · 当年天气扰动 ${signed(m.weatherAnomaly)}°C</p><small>本市累计 CO₂ 的全球增温贡献约 ${(state.localCO2*.00045).toFixed(6)}°C。背景路径是游戏情景；长期升温不代表每一年都比上一年热。</small>`;
 $('#event-archive').innerHTML=SHOCKS.map(e=>`<p><a href="${e.source}" target="_blank" rel="noopener noreferrer">${e.period} · ${e.historical} ↗</a><br><small>${e.summary}</small></p>`).join('');
 $('#population-flow').textContent=state.last?`人口年报：出生 +${m.births}，普通死亡 −${m.ordinaryDeaths}，高温死亡 −${m.heatDeaths}，污染额外死亡 −${m.pollutionDeaths}，净迁入 ${signed(m.migration)}。年末 ${m.population.toLocaleString()} 人。`:'开局 10 万居民。出生、死亡、就业、住房与环境决定城市人口变化。';
 $('#world-news').innerHTML=state.last?.events.length?state.last.events.map(e=>`<article class="news-card"><span>${e.scale==='large'?'重大事件':'外部事件'} · 剩余 ${e.remaining} 年</span><h3>${e.name}</h3><p>${e.summary}</p><p>本年基础影响：就业 ${signed(e.jobs)} 个百分点 · 财政 ${signed(e.cash)} · 排放 ${signed(e.emissions)}</p><a href="${e.source}" target="_blank" rel="noopener noreferrer">历史参考：${e.period} ${e.historical} ↗</a><small>历史机制启发的虚构事件，非未来预测；效果数值为游戏设定。</small></article>`).join(''):'<p class="model-note">尚无本年事件。执行政策后，年报会揭晓被动冲击。</p>';
}
function landClick(e){const b=e.target.closest('[data-land]');if(!b)return;const k=b.dataset.land;const text={forest:'森林占地并缓解本地热岛。造林需要空地和生长时间。',farmland:'农田提供食物承载能力，人口过多会带来供应压力。',residential:'每格已建成住宅提供 7,000 人住房容量；施工期间尚不可入住。',industry:'工业提供岗位和税收，也消耗水、矿产并增加排放；可通过退役产能释放土地。',energy:'能源采集、化石发电及清洁设施生命周期都计入排放；风机和采集设备比例随化石依赖改变。',water:'水色随污染变化。受污染水体与缺水可放大暴露；清洁水域不会自动增加死亡，净水设施可削减风险。',vacant:'住宅、工业、能源和造林都竞争有限空地。'};$('#land-detail').textContent=landMeta[k][0]+'：'+state.land[k]+' 格。'+text[k];}
$('#city-map').addEventListener('click',landClick);$('#city-map').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();landClick(e);}});$('#animation-toggle').addEventListener('click',()=>{const paused=$('#city-map').classList.toggle('paused');$('#animation-toggle').setAttribute('aria-pressed',String(paused));$('#animation-toggle').textContent=paused?'播放动画':'暂停动画';});$('#land-legend').addEventListener('click',landClick);

let newsYear=null,pendingLevels=false,newsTimer;
function renderNews(){const box=$('#news');clearTimeout(newsTimer);const events=state.last&&state.last.year===newsYear?state.last.events.filter(e=>e.at===newsYear):[];box.hidden=!events.length;const fx=e=>['jobs','cash','emissions','heat','water','minerals'].filter(k=>e[k]).map(k=>`<span class="${(k==='emissions'||k==='heat')===(e[k]>0)?'bad':'good'}">${t('fx_'+k)} ${signed(e[k])}</span>`).join('');if(events.length)newsTimer=setTimeout(()=>{newsYear=null;renderNews();},9000);box.innerHTML=events.map(e=>`<article class="news-item ${e.scale}"><div class="news-top"><span>${t('news')} · ${2026+e.at} · ${e.scale==='large'?t('newsLarge',{n:e.years}):t('newsSmall')}</span><button class="news-close" data-news-close aria-label="${t('close')}">×</button></div><h3>${eventName(e)}</h3><p>${eventSummary(e)}</p><div class="news-fx">${fx(e)}</div></article>`).join('');}
$('#news').addEventListener('click',e=>{if(e.target.closest('[data-news-close]')){newsYear=null;renderNews();}});
$('#lang-button').addEventListener('click',()=>{setLang(lang==='en'?'zh':'en');render();});
document.body.classList.toggle('player',!EDITOR);$('#lang-button').hidden=EDITOR;
document.body.dataset.tab='city';$('#tabbar').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;document.body.dataset.tab=b.dataset.tab;$('#tabbar').querySelectorAll('button').forEach(x=>x.setAttribute('aria-current',String(x===b)));window.scrollTo(0,0);});
if(hasLang())setLang(lang);initStore().then(render).catch(()=>{});render();save();if(!hasLang()){setLang(/^zh/i.test(navigator.language)?'zh':'en');render();open(`<h2 id="dialog-title">选择语言 · Choose your language</h2><button class="primary-button" data-lang="zh"><span>中文</span>${icon('arrow')}</button><button class="primary-button" data-lang="en"><span>English</span>${icon('arrow')}</button>`);try{localStorage.removeItem('tomorrow-city.lang');}catch{}}else if(state.finished)showResult();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const reg=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
reg({name:'read_city_state',description:'Read annual policy simulation state, effects and policy availability.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:summary});
reg({name:'enact_policy_and_advance_year',description:'Enact one affordable policy (or wait) and settle exactly one simulated year.',inputSchema:{type:'object',properties:{policyId:{type:'string',enum:[...POLICIES.map(p=>p.id),'wait']}},required:['policyId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||![...POLICIES.map(p=>p.id),'wait'].includes(input.policyId))throw new Error('无效政策');if($('#game-dialog').open)throw new Error('请先关闭当前弹窗');return enact(input.policyId==='wait'?null:input.policyId);}});
window.addEventListener('pagehide',e=>{if(!e.persisted)lifecycle.abort();});}
